window.hapuga_elements={lib:{},assets:[],shapes:{},setup:function(h){
const n=h.MovieClip,e=h.Container,a=h.Sprite,z=h.Text,A=h.Graphics;

const mkBtn=(lbl,w,ht,fill,bord,tc)=>{
  fill=fill||0x1a3a0a;bord=bord||0x3a7a1a;tc=tc||'#90d040';
  const bg=new A();bg.beginFill(fill,1);bg.lineStyle(1,bord);bg.drawRoundedRect(0,0,w,ht,4);bg.endFill();
  const t=new z(lbl,{fontFamily:'Southbank LT',fontSize:12,fontWeight:'bold',fill:tc,align:'center',wordWrap:true,wordWrapWidth:w-6});
  t.anchor.set(0.5,0.5);t.x=w/2;t.y=ht/2;
  const c=new e();c.addChild(bg,t);c.interactive=true;c.buttonMode=true;
  c.on('mouseover',()=>bg.tint=0xddeecc);c.on('mouseout',()=>bg.tint=0xffffff);
  c._bg=bg;c._txt=t;return c;
};

// ── Таймер до следующего появления ────────────────────────────────
hapuga_elements.lib.Hapuga_timer=class extends e{
  constructor(){
    super();
    const bg=new A();bg.beginFill(0x1a0e00,0.95);bg.lineStyle(1,0x7a5010,0.8);bg.drawRoundedRect(0,0,380,44,6);bg.endFill();this.addChild(bg);
    const ic=new z('🕵',{fontFamily:'Arial',fontSize:26});ic.x=10;ic.y=6;this.addChild(ic);
    const lt=new z('Хапуга появится через:',{fontFamily:'Southbank LT',fontSize:11,fill:'#7a5a2a'});lt.x=48;lt.y=8;this.addChild(lt);
    const tt=new z('',{fontFamily:'Southbank LT',fontSize:16,fontWeight:'bold',fill:'#e0a030'});tt.x=48;tt.y=24;this[tt.name='time_txt']=tt;this.addChild(tt);
  }
};

// ── Карточка товара Хапуги ─────────────────────────────────────────
hapuga_elements.lib.Hap_item=class extends e{
  constructor(){
    super();
    this.bg_mc=new A();this._drawBg(false);this.addChild(this.bg_mc);
    // Иконка
    const ic=new z('',{fontFamily:'Arial',fontSize:42,align:'center'});ic.anchor.set(0.5,0);ic.x=56;ic.y=10;this[ic.name='icon_txt']=ic;this.addChild(ic);
    // Бейдж «РЕДКОСТЬ»
    const rbg=new A();rbg.beginFill(0x2a1800,1);rbg.lineStyle(1,0x8a5010,0.8);rbg.drawRoundedRect(0,0,100,18,3);rbg.endFill();rbg.x=6;rbg.y=68;
    const rt=new z('',{fontFamily:'Southbank LT',fontSize:9,fontWeight:'bold',fill:'#e0a030',align:'center'});rt.anchor.set(0.5,0.5);rt.x=50;rt.y=9;
    const rw=new e();rw.addChild(rbg,rt);this[rt.name='rarity_txt']=rt;this[rw.name='rarity_badge']=rw;this.addChild(rw);
    // Название
    const nt=new z('',{fontFamily:'Southbank LT',fontSize:13,fontWeight:'bold',fill:'#e0c060',wordWrap:true,wordWrapWidth:220});nt.x=120;nt.y=10;this[nt.name='name_txt']=nt;this.addChild(nt);
    // Описание
    const dt=new z('',{fontFamily:'Arial',fontSize:11,fill:'#7a6030',wordWrap:true,wordWrapWidth:220});dt.x=120;dt.y=34;this[dt.name='desc_txt']=dt;this.addChild(dt);
    // Оригинальная цена (зачёркнута)
    const ot=new z('',{fontFamily:'Southbank LT',fontSize:11,fill:'#5a4020'});ot.x=120;ot.y=66;this[ot.name='orig_price_txt']=ot;this.addChild(ot);
    // Скидка бейдж
    const dbg=new A();dbg.beginFill(0x7a1000,1);dbg.lineStyle(1,0xcc2000);dbg.drawRoundedRect(0,0,56,22,3);dbg.endFill();dbg.x=6;dbg.y=6;
    const dt2=new z('',{fontFamily:'Southbank LT',fontSize:11,fontWeight:'bold',fill:'#ff6040',align:'center'});dt2.anchor.set(0.5,0.5);dt2.x=28;dt2.y=11;
    const dw=new e();dw.addChild(dbg,dt2);this[dt2.name='discount_txt']=dt2;this[dw.name='discount_badge']=dw;this.addChild(dw);
    // Цена со скидкой + кнопка купить
    const pt=new z('',{fontFamily:'Southbank LT',fontSize:14,fontWeight:'bold',fill:'#f0c040'});pt.x=120;pt.y=82;this[pt.name='sale_price_txt']=pt;this.addChild(pt);
    const buy=mkBtn('КУПИТЬ',90,32,0x3a2000,0x9a6010,'#f0c040');buy.x=248;buy.y=58;this[buy.name='butt_buy']=buy;this.addChild(buy);
    // Sold out оверлей
    const sob=new A();sob.beginFill(0x000000,0.6);sob.drawRoundedRect(0,0,350,102,4);sob.endFill();sob.visible=false;
    const sot=new z('РАСКУПЛЕНО',{fontFamily:'Southbank LT',fontSize:16,fontWeight:'bold',fill:'#cc4444',align:'center'});sot.anchor.set(0.5,0.5);sot.x=175;sot.y=51;
    const sow=new e();sow.addChild(sob,sot);sow.visible=false;this[sow.name='sold_out']=sow;this.addChild(sow);
  }
  _drawBg(hover){
    this.bg_mc.clear();
    this.bg_mc.beginFill(hover?0x1e1200:0x120c02,hover?0.98:0.94);
    this.bg_mc.lineStyle(hover?2:1,hover?0x9a6a10:0x4a3010,hover?0.9:0.6);
    this.bg_mc.drawRoundedRect(0,0,350,102,6);this.bg_mc.endFill();
  }
};

// ── Главное окно Хапуги ────────────────────────────────────────────
hapuga_elements.lib.Hapuga_win=class extends e{
  constructor(){
    super();
    const wb=new A();wb.beginFill(0x0c0800,0.97);wb.lineStyle(2,0x6a4a10,0.9);wb.drawRoundedRect(0,0,1200,524,6);wb.endFill();this.addChild(wb);
    const hb=new A();hb.beginFill(0x140e00,1);hb.drawRect(2,2,1196,42);hb.endFill();
    const hl=new A();hl.lineStyle(1,0x6a4a10,0.5);hl.moveTo(2,45);hl.lineTo(1198,45);this.addChild(hb,hl);
    const ttl=new z('ХАПУГА',{fontFamily:'Southbank LT',fontSize:18,fontWeight:'bold',fill:'#e0c040',letterSpacing:5,dropShadow:true,dropShadowDistance:2,dropShadowColor:'#000'});ttl.x=20;ttl.y=12;this.addChild(ttl);
    const sub=new z('Загадочный торговец · Появляется раз в несколько часов',{fontFamily:'Arial',fontSize:11,fill:'#7a5a20',fontStyle:'italic'});sub.x=180;sub.y=17;this.addChild(sub);
    const cbg=new A();cbg.beginFill(0x3a1010,1);cbg.lineStyle(1,0x882222);cbg.drawRoundedRect(0,0,30,30,4);cbg.endFill();
    const ctx=new z('×',{fontFamily:'Arial',fontSize:22,fill:'#cc4444'});ctx.anchor.set(0.5,0.5);ctx.x=15;ctx.y=15;
    const cl=new e();cl.addChild(cbg,ctx);cl.x=1162;cl.y=7;cl.interactive=true;cl.buttonMode=true;cl.on('mouseover',()=>cbg.tint=0xddaaaa);cl.on('mouseout',()=>cbg.tint=0xffffff);
    this[cl.name='butt_close']=cl;this.addChild(cl);
    // Таймер
    const timer=new hapuga_elements.lib.Hapuga_timer();timer.x=800;timer.y=6;this[timer.name='hap_timer']=timer;this.addChild(timer);
    // Панель с аватаром Хапуги
    const avbg=new A();avbg.beginFill(0x180e00,0.95);avbg.lineStyle(1,0x6a4a10,0.7);avbg.drawRoundedRect(0,0,140,420,6);avbg.endFill();avbg.x=10;avbg.y=50;this.addChild(avbg);
    const avc=new z('🕵',{fontFamily:'Arial',fontSize:80,align:'center'});avc.anchor.set(0.5,0);avc.x=80;avc.y=70;this.addChild(avc);
    const avname=new z('Хапуга',{fontFamily:'Southbank LT',fontSize:14,fontWeight:'bold',fill:'#e0b030',align:'center'});avname.anchor.set(0.5,0);avname.x=80;avname.y=172;this.addChild(avname);
    const avquote=new z('"Только для тебя,\nсталкер..."',{fontFamily:'Arial',fontSize:10,fill:'#7a5a20',fontStyle:'italic',align:'center',wordWrap:true,wordWrapWidth:130});avquote.anchor.set(0.5,0);avquote.x=80;avquote.y=198;this.addChild(avquote);
    // Счётчик обновления
    const rcnt=new z('',{fontFamily:'Southbank LT',fontSize:10,fill:'#5a4010',align:'center'});rcnt.anchor.set(0.5,0);rcnt.x=80;rcnt.y=260;this[rcnt.name='refresh_cnt_txt']=rcnt;this.addChild(rcnt);
    const rbtn=mkBtn('↻ ОБНОВИТЬ\n(25🚬)',130,40,0x2a1800,0x8a5010,'#e0a030');rbtn.x=15;rbtn.y=320;this[rbtn.name='butt_refresh']=rbtn;this.addChild(rbtn);
    // Сетка товаров 2×4 (8 товаров)
    const grid=new e();grid.x=160;grid.y=52;
    for(let i=0;i<8;i++){
      const it=new hapuga_elements.lib.Hap_item();
      it.x=(i%2)*(350+14);it.y=Math.floor(i/2)*(102+8);
      grid['item_'+i]=it;grid.addChild(it);
    }
    this[grid.name='item_grid']=grid;this.addChild(grid);
    // «Нет в наличии» оверлей (когда торговец ушёл)
    const gone=new e();gone.visible=false;
    const gonebg=new A();gonebg.beginFill(0x000000,0.7);gonebg.drawRect(0,0,1200,524);gonebg.endFill();
    const gonet=new z('Хапуга ушёл...\nПриходи позже',{fontFamily:'Southbank LT',fontSize:28,fontWeight:'bold',fill:'#c8a030',align:'center',dropShadow:true,dropShadowDistance:3,dropShadowColor:'#000'});
    gonet.anchor.set(0.5,0.5);gonet.x=600;gonet.y=260;
    gone.addChild(gonebg,gonet);this[gone.name='gone_overlay']=gone;this.addChild(gone);
  }
};

hapuga_elements.lib.hapuga_elements=class extends n{
  constructor(){super({duration:1,framerate:30});const b=new hapuga_elements.lib.Hapuga_win();this[b.name='hapuga_win']=b;this.addChild(b);}
};
hapuga_elements.stage=hapuga_elements.lib.hapuga_elements}};
